def surge_bands(changes, target):
    counts = {0: 1}
    latest = {0: 0}
    total = 0
    bands = 0
    shortest = 0
    for end in range(1, len(changes) + 1):
        total += changes[end - 1]
        needed = total - target
        if needed in counts:
            bands += counts[needed]
            length = end - latest[needed]
            if shortest == 0 or length < shortest:
                shortest = length
        if total not in counts:
            counts[total] = 0
        counts[total] += 1
        latest[total] = end
    return [bands, shortest]

